import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/architecture/aoi.html","title":"AOI九宫格系统详解","lang":"en-US","frontmatter":{"title":"AOI九宫格系统详解","icon":"eye","order":4,"category":["架构","AOI"],"tag":["AOI","九宫格","视野管理"]},"filePathRelative":"architecture/aoi.md","git":{"createdTime":1773827303000,"updatedTime":1773827303000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),a={name:`aoi.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="aoi九宫格系统-高效的视野管理" tabindex="-1"><a class="header-anchor" href="#aoi九宫格系统-高效的视野管理"><span>AOI九宫格系统 - 高效的视野管理</span></a></h1><h2 id="目录" tabindex="-1"><a class="header-anchor" href="#目录"><span>目录</span></a></h2><ul><li><a href="#%E4%BB%80%E4%B9%88%E6%98%AFaoi">什么是AOI</a></li><li><a href="#%E4%B8%BA%E4%BB%80%E4%B9%88%E9%9C%80%E8%A6%81aoi%E7%B3%BB%E7%BB%9F">为什么需要AOI系统</a></li><li><a href="#%E4%B8%BA%E4%BB%80%E4%B9%88%E4%B9%9D%E5%AE%AB%E6%A0%BC%E6%98%AF%E9%AB%98%E6%95%88%E7%9A%84">为什么九宫格是高效的</a></li><li><a href="#%E6%80%8E%E4%B9%88%E5%8F%91%E7%8E%B0%E7%9B%AE%E6%A0%87">怎么发现目标</a></li><li><a href="#%E6%80%8E%E4%B9%88%E5%8E%BB%E9%87%8D">怎么去重</a></li><li><a href="#%E5%AE%8C%E6%95%B4%E5%AE%9E%E7%8E%B0%E7%A4%BA%E4%BE%8B">完整实现示例</a></li></ul><hr><h2 id="什么是aoi" tabindex="-1"><a class="header-anchor" href="#什么是aoi"><span>什么是AOI？</span></a></h2><p><strong>AOI (Area of Interest)</strong> 即&quot;感兴趣区域&quot;，在游戏中特指<strong>视野管理</strong>——每个玩家只能看到自己周围一定范围内的其他实体（怪物、NPC、其他玩家）。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">例如：玩家只能看到周围100米内的实体</span>
<span class="line">        👤 → 感知范围 100m</span>
<span class="line">           ╔═════════╗</span>
<span class="line">           ║  👻 🐉  ║</span>
<span class="line">           ║ 👤 👾  ║</span>
<span class="line">           ╚═════════╝</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="为什么需要aoi系统" tabindex="-1"><a class="header-anchor" href="#为什么需要aoi系统"><span>为什么需要AOI系统？</span></a></h2><h3 id="问题场景" tabindex="-1"><a class="header-anchor" href="#问题场景"><span>问题场景</span></a></h3><p>假设游戏世界有 <strong>10,000个玩家</strong>：</p><ul><li>如果没有AOI：每次移动需要通知 <strong>9,999个玩家</strong> → 网络爆炸</li><li>有AOI（感知100人）：每次只需通知 <strong>100个玩家</strong> → 可接受</li></ul><hr><h2 id="为什么九宫格是高效的" tabindex="-1"><a class="header-anchor" href="#为什么九宫格是高效的"><span>为什么九宫格是高效的？</span></a></h2><h3 id="核心思想-空间换时间" tabindex="-1"><a class="header-anchor" href="#核心思想-空间换时间"><span>核心思想：空间换时间</span></a></h3><p>将游戏世界划分为固定的网格，每个格子记录其中的实体。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">世界地图划分:</span>
<span class="line">┌──────┬──────┬──────┬──────┐</span>
<span class="line">│  0   │  1   │  2   │  3   │</span>
<span class="line">├──────┼──────┼──────┼──────┤</span>
<span class="line">│  4   │  5   │  6   │  7   │</span>
<span class="line">├──────┼──────┼──────┼──────┤</span>
<span class="line">│  8   │  9   │ 10   │ 11   │</span>
<span class="line">├──────┼──────┼──────┼──────┤</span>
<span class="line">│ 12   │ 13   │ 14   │ 15   │</span>
<span class="line">└──────┴──────┴──────┴──────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="九宫格原理" tabindex="-1"><a class="header-anchor" href="#九宫格原理"><span>九宫格原理</span></a></h3><p>当玩家在格子(5)时，只需要检查<strong>周围9个格子</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">           ┌───┬───┬───┐</span>
<span class="line">           │ 1 │ 2 │ 3 │  ← 只需检查这9个格子</span>
<span class="line">           ├───┼───┼───┤</span>
<span class="line">           │ 4 │ 👤│ 6 │</span>
<span class="line">           ├───┼───┼───┤</span>
<span class="line">           │ 7 │ 8 │ 9 │</span>
<span class="line">           └───┴───┴───┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="为什么高效" tabindex="-1"><a class="header-anchor" href="#为什么高效"><span>为什么高效？</span></a></h3><table><thead><tr><th>方案</th><th>查找复杂度</th><th>移动更新</th><th>说明</th></tr></thead><tbody><tr><td><strong>全表扫描</strong></td><td>O(N)</td><td>O(N)</td><td>遍历所有实体，不实用</td></tr><tr><td><strong>四叉树</strong></td><td>O(log N)</td><td>O(log N)</td><td>树结构复杂，实现难</td></tr><tr><td><strong>十字链表</strong></td><td>O(1)</td><td>O(1)</td><td>只能处理方形视野</td></tr><tr><td><strong>九宫格</strong></td><td>O(1)</td><td>O(1)</td><td>简单、高效、稳定</td></tr></tbody></table><p><strong>九宫格的优势：</strong></p><ol><li><strong>O(1)查找</strong>：直接根据坐标算出格子编号</li><li><strong>O(1)更新</strong>：跨格子时只需更新2个格子</li><li><strong>实现简单</strong>：数组即可存储</li><li><strong>内存友好</strong>：不需要复杂的树结构</li></ol><hr><h2 id="怎么发现目标-核心算法" tabindex="-1"><a class="header-anchor" href="#怎么发现目标-核心算法"><span>怎么发现目标？（核心算法）</span></a></h2><h3 id="_1-坐标-→-格子编号" tabindex="-1"><a class="header-anchor" href="#_1-坐标-→-格子编号"><span>1. 坐标 → 格子编号</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 假设格子大小 100x100，原点在地图左上角</span></span>
<span class="line"><span class="token keyword">int</span> gridX <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">int</span><span class="token punctuation">)</span><span class="token punctuation">(</span>posX <span class="token operator">/</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">int</span> gridY <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">int</span><span class="token punctuation">)</span><span class="token punctuation">(</span>posY <span class="token operator">/</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">int</span> gridIndex <span class="token operator">=</span> gridY <span class="token operator">*</span> widthInGrids <span class="token operator">+</span> gridX<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-获取九宫格索引" tabindex="-1"><a class="header-anchor" href="#_2-获取九宫格索引"><span>2. 获取九宫格索引</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span><span class="token keyword">int</span><span class="token operator">&gt;</span> <span class="token function">getNineGrids</span><span class="token punctuation">(</span><span class="token keyword">int</span> gridX<span class="token punctuation">,</span> <span class="token keyword">int</span> gridY<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span><span class="token keyword">int</span><span class="token operator">&gt;</span> grids<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> dy <span class="token operator">=</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span> dy <span class="token operator">&lt;=</span> <span class="token number">1</span><span class="token punctuation">;</span> dy<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> dx <span class="token operator">=</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span> dx <span class="token operator">&lt;=</span> <span class="token number">1</span><span class="token punctuation">;</span> dx<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">int</span> nx <span class="token operator">=</span> gridX <span class="token operator">+</span> dx<span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">int</span> ny <span class="token operator">=</span> gridY <span class="token operator">+</span> dy<span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>nx <span class="token operator">&gt;=</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span> nx <span class="token operator">&lt;</span> mapWidth <span class="token operator">&amp;&amp;</span> ny <span class="token operator">&gt;=</span> <span class="token number">0</span> <span class="token operator">&amp;&amp;</span> ny <span class="token operator">&lt;</span> mapHeight<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                grids<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>ny <span class="token operator">*</span> widthInGrids <span class="token operator">+</span> nx<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> grids<span class="token punctuation">;</span>  <span class="token comment">// 最多9个格子</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-收集视野内实体" tabindex="-1"><a class="header-anchor" href="#_3-收集视野内实体"><span>3. 收集视野内实体</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token function">getEntitiesInView</span><span class="token punctuation">(</span>Position pos<span class="token punctuation">,</span> <span class="token keyword">float</span> viewRadius<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> result<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 1. 获取九宫格</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span><span class="token keyword">int</span><span class="token operator">&gt;</span> grids <span class="token operator">=</span> <span class="token function">getNineGrids</span><span class="token punctuation">(</span>pos<span class="token punctuation">.</span>x <span class="token operator">/</span> <span class="token number">100</span><span class="token punctuation">,</span> pos<span class="token punctuation">.</span>y <span class="token operator">/</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. 遍历九宫格内的实体</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> gridId <span class="token operator">:</span> grids<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity <span class="token operator">:</span> gridMap<span class="token punctuation">[</span>gridId<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 3. 精确距离判断（过滤九宫格边角）</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">distance</span><span class="token punctuation">(</span>pos<span class="token punctuation">,</span> entity<span class="token operator">-&gt;</span>pos<span class="token punctuation">)</span> <span class="token operator">&lt;=</span> viewRadius<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                result<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> result<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="怎么去重-关键问题" tabindex="-1"><a class="header-anchor" href="#怎么去重-关键问题"><span>怎么去重？（关键问题）</span></a></h2><h3 id="问题-九宫格边界会重复计算" tabindex="-1"><a class="header-anchor" href="#问题-九宫格边界会重复计算"><span>问题：九宫格边界会重复计算</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">     格子A    格子B</span>
<span class="line">┌────────┬────────┐</span>
<span class="line">│  👾1   │  👾2   │  👾1和👾2都在视野内</span>
<span class="line">│    👤  ├────────┤  但👾2会被计算两次！</span>
<span class="line">│  👾3   │  👾4   │</span>
<span class="line">└────────┴────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="去重方案" tabindex="-1"><a class="header-anchor" href="#去重方案"><span>去重方案</span></a></h3><h4 id="方案1-用集合-最简单" tabindex="-1"><a class="header-anchor" href="#方案1-用集合-最简单"><span>方案1: 用集合（最简单）</span></a></h4><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line">std<span class="token double-colon punctuation">::</span>unordered_set<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> entitySet<span class="token punctuation">;</span>  <span class="token comment">// 自动去重</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> gridId <span class="token operator">:</span> nineGrids<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity <span class="token operator">:</span> gridMap<span class="token punctuation">[</span>gridId<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        entitySet<span class="token punctuation">.</span><span class="token function">insert</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// insert自动去重</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="方案2-位标记法-高性能" tabindex="-1"><a class="header-anchor" href="#方案2-位标记法-高性能"><span>方案2: 位标记法（高性能）</span></a></h4><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 每个实体有一个frameId标记</span></span>
<span class="line"><span class="token keyword">struct</span> <span class="token class-name">Entity</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">uint32_t</span> viewFrameId<span class="token punctuation">;</span>  <span class="token comment">// 每帧+1</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">static</span> <span class="token keyword">uint32_t</span> currentFrameId <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token function">getEntitiesInView</span><span class="token punctuation">(</span>Position pos<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    currentFrameId<span class="token operator">++</span><span class="token punctuation">;</span>  <span class="token comment">// 每次查询递增</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> result<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> gridId <span class="token operator">:</span> nineGrids<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity <span class="token operator">:</span> gridMap<span class="token punctuation">[</span>gridId<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>entity<span class="token operator">-&gt;</span>viewFrameId <span class="token operator">!=</span> currentFrameId<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                entity<span class="token operator">-&gt;</span>viewFrameId <span class="token operator">=</span> currentFrameId<span class="token punctuation">;</span>  <span class="token comment">// 标记</span></span>
<span class="line">                result<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token comment">// else: 已经添加过，跳过</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> result<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="完整实现示例" tabindex="-1"><a class="header-anchor" href="#完整实现示例"><span>完整实现示例</span></a></h2><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token keyword">class</span> <span class="token class-name">AOIManager</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">struct</span> <span class="token class-name">Grid</span> <span class="token punctuation">{</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> entities<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">int</span> mapWidth<span class="token punctuation">;</span>       <span class="token comment">// 地图宽度（格子数）</span></span>
<span class="line">    <span class="token keyword">int</span> mapHeight<span class="token punctuation">;</span>      <span class="token comment">// 地图高度（格子数）</span></span>
<span class="line">    <span class="token keyword">float</span> gridSize<span class="token punctuation">;</span>     <span class="token comment">// 每格大小</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Grid<span class="token operator">&gt;</span> grids<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token comment">// 进入游戏世界</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">enter</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity<span class="token punctuation">,</span> Position pos<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">int</span> gridId <span class="token operator">=</span> <span class="token function">getGridId</span><span class="token punctuation">(</span>pos<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        grids<span class="token punctuation">[</span>gridId<span class="token punctuation">]</span><span class="token punctuation">.</span>entities<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        entity<span class="token operator">-&gt;</span>gridId <span class="token operator">=</span> gridId<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 通知周围玩家</span></span>
<span class="line">        <span class="token function">notifyEnter</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 移动</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">move</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity<span class="token punctuation">,</span> Position newPos<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">int</span> oldGrid <span class="token operator">=</span> entity<span class="token operator">-&gt;</span>gridId<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">int</span> newGrid <span class="token operator">=</span> <span class="token function">getGridId</span><span class="token punctuation">(</span>newPos<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        entity<span class="token operator">-&gt;</span>pos <span class="token operator">=</span> newPos<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>oldGrid <span class="token operator">!=</span> newGrid<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 跨格子：从旧格子移除，加入新格子</span></span>
<span class="line">            <span class="token function">removeFromGrid</span><span class="token punctuation">(</span>entity<span class="token punctuation">,</span> oldGrid<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">addToGrid</span><span class="token punctuation">(</span>entity<span class="token punctuation">,</span> newGrid<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">            <span class="token comment">// 重新计算视野变化</span></span>
<span class="line">            <span class="token function">notifyViewChange</span><span class="token punctuation">(</span>entity<span class="token punctuation">,</span> oldGrid<span class="token punctuation">,</span> newGrid<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 离开</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">leave</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">removeFromGrid</span><span class="token punctuation">(</span>entity<span class="token punctuation">,</span> entity<span class="token operator">-&gt;</span>gridId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">notifyLeave</span><span class="token punctuation">(</span>entity<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">private</span><span class="token operator">:</span></span>
<span class="line">    <span class="token comment">// 获取视野内实体（带去重）</span></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> <span class="token function">getViewers</span><span class="token punctuation">(</span>Entity<span class="token operator">*</span> entity<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">static</span> <span class="token keyword">uint32_t</span> frameId <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">        frameId<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>vector<span class="token operator">&lt;</span>Entity<span class="token operator">*</span><span class="token operator">&gt;</span> result<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">int</span> gx <span class="token operator">=</span> entity<span class="token operator">-&gt;</span>gridId <span class="token operator">%</span> mapWidth<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">int</span> gy <span class="token operator">=</span> entity<span class="token operator">-&gt;</span>gridId <span class="token operator">/</span> mapWidth<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> dy <span class="token operator">=</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span> dy <span class="token operator">&lt;=</span> <span class="token number">1</span><span class="token punctuation">;</span> dy<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">int</span> dx <span class="token operator">=</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span> dx <span class="token operator">&lt;=</span> <span class="token number">1</span><span class="token punctuation">;</span> dx<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">int</span> nx <span class="token operator">=</span> gx <span class="token operator">+</span> dx<span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">int</span> ny <span class="token operator">=</span> gy <span class="token operator">+</span> dy<span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token punctuation">(</span>nx <span class="token operator">&lt;</span> <span class="token number">0</span> <span class="token operator">||</span> nx <span class="token operator">&gt;=</span> mapWidth <span class="token operator">||</span> ny <span class="token operator">&lt;</span> <span class="token number">0</span> <span class="token operator">||</span> ny <span class="token operator">&gt;=</span> mapHeight<span class="token punctuation">)</span> <span class="token keyword">continue</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">                <span class="token keyword">int</span> neighborGrid <span class="token operator">=</span> ny <span class="token operator">*</span> mapWidth <span class="token operator">+</span> nx<span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">for</span> <span class="token punctuation">(</span>Entity<span class="token operator">*</span> other <span class="token operator">:</span> grids<span class="token punctuation">[</span>neighborGrid<span class="token punctuation">]</span><span class="token punctuation">.</span>entities<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token keyword">if</span> <span class="token punctuation">(</span>other<span class="token operator">-&gt;</span>viewFrameId <span class="token operator">!=</span> frameId<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                        other<span class="token operator">-&gt;</span>viewFrameId <span class="token operator">=</span> frameId<span class="token punctuation">;</span></span>
<span class="line">                        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">inRange</span><span class="token punctuation">(</span>entity<span class="token punctuation">,</span> other<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                            result<span class="token punctuation">.</span><span class="token function">push_back</span><span class="token punctuation">(</span>other<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                        <span class="token punctuation">}</span></span>
<span class="line">                    <span class="token punctuation">}</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">        <span class="token keyword">return</span> result<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><table><thead><tr><th>要点</th><th>关键</th></tr></thead><tbody><tr><td><strong>AOI本质</strong></td><td>空间过滤，只处理视野内的实体</td></tr><tr><td><strong>九宫格高效</strong></td><td>O(1)查找，O(1)更新，实现简单</td></tr><tr><td><strong>发现目标</strong></td><td>坐标→格子→九宫格→遍历+距离判断</td></tr><tr><td><strong>去重方法</strong></td><td>位标记法 &gt; 集合法（性能）</td></tr></tbody></table><p>这就是为什么大多数MMORPG游戏服务器都采用九宫格AOI系统！</p>`,48)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};